import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

// issue #12: the customer discount must be applied exactly once.
test('total applies the customer discount once (under 10 lines)', () => {
  // 1,000 x (1 - 0.1) = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('total applies the 5% bulk discount once, after the customer discount (10 lines)', () => {
  // 10,000 x (1 - 0.1) = 9,000; 9,000 x (1 - 0.05) = 8,550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('total applies no bulk discount to a 9-line cart', () => {
  // 9,000 x (1 - 0.1) = 8,100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('total with discount rate 0 is unchanged by the issue #12 fix', () => {
  // bulk discount only: 10,000 x (1 - 0.05) = 9,500
  assert.equal(total(lines(10, 1000), 0), 9500);
  // 330 x 0.95 = 313.5, rounded to 314 as before the fix
  assert.equal(total(lines(10, 33), 0), 314);
});
